hand = '2S 8H 6S 8D JH'

    def _hand_score(hand):
        """Return a comparable score tuple for a five-card hand string."""
        cards = hand.split()
        ranks = [_RANKS[card[:-1]] for card in cards]
        suits = [card[-1] for card in cards]

        is_flush = len(set(suits)) == 1

        ordered = sorted(ranks, reverse=True)
        is_straight = ordered == [ordered[0] - i for i in range(5)]
        # Ace can start a straight: A 2 3 4 5 is a 5-high straight.
        if ordered == [14, 5, 4, 3, 2]:
            is_straight = True
            straight_high = 5
        elif is_straight:
            straight_high = ordered[0]

        if is_straight and is_flush:
            return (8, straight_high)
        if is_straight:
            return (4, straight_high)

        # Group ranks by count, highest rank first.
        counts = {}
        for rank in ranks:
            counts[rank] = counts.get(rank, 0) + 1
        by_rank = sorted(counts.items(), key=lambda item: (-item[1], -item[0]))

        if is_flush:
            return (5, *ordered)
        if by_rank[0][1] == 4:
            quad, kicker = by_rank
            return (7, quad[0], kicker[0])
        if by_rank[0][1] == 3 and by_rank[1][1] == 2:
            return (6, by_rank[0][0], by_rank[1][0])
